CREATE TABLE public.fx_currencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code ~ '^[A-Z]{3}$' AND code <> 'LKR'),name text NOT NULL CHECK(length(trim(name))>0),active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.fx_currencies TO authenticated; GRANT ALL ON public.fx_currencies TO service_role;
ALTER TABLE public.fx_currencies ENABLE ROW LEVEL SECURITY;
CREATE POLICY fx_currency_read ON public.fx_currencies FOR SELECT TO authenticated USING(public.staff_can('View currency reports',NULL) OR public.staff_can('Manage currency exchange',NULL));
CREATE TABLE public.fx_accounts(branch_id text NOT NULL REFERENCES public.branches(id),currency text NOT NULL CHECK(currency='LKR' OR currency ~ '^[A-Z]{3}$'),balance numeric(20,2) NOT NULL DEFAULT 0 CHECK(balance>=0),cost_lkr numeric(20,2) NOT NULL DEFAULT 0 CHECK(cost_lkr>=0),PRIMARY KEY(branch_id,currency));
GRANT SELECT ON public.fx_accounts TO authenticated; GRANT ALL ON public.fx_accounts TO service_role;
ALTER TABLE public.fx_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY fx_account_read ON public.fx_accounts FOR SELECT TO authenticated USING(public.staff_can('View currency reports',branch_id) OR public.staff_can('Manage currency exchange',branch_id));
CREATE TABLE public.fx_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),currency text NOT NULL,kind text NOT NULL CHECK(kind IN('Buy','Sell','Funding','Withdrawal')),amount numeric(20,2) NOT NULL CHECK(amount>0),rate numeric(20,6) NOT NULL CHECK(rate>0),lkr_total numeric(20,2) NOT NULL CHECK(lkr_total>0),cost_lkr numeric(20,2) NOT NULL DEFAULT 0,profit_lkr numeric(20,2) NOT NULL DEFAULT 0,counterparty text NOT NULL DEFAULT '',reference text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',date date NOT NULL DEFAULT (now() AT TIME ZONE 'Asia/Colombo')::date,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL);
GRANT SELECT ON public.fx_entries TO authenticated; GRANT ALL ON public.fx_entries TO service_role;
ALTER TABLE public.fx_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY fx_entry_read ON public.fx_entries FOR SELECT TO authenticated USING(public.staff_can('View currency reports',branch_id) OR public.staff_can('Manage currency exchange',branch_id));
CREATE INDEX fx_entry_branch_date ON public.fx_entries(branch_id,date);
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.save_staff_role(jsonb)'::regprocedure) INTO d;d:=replace(d,'''Manage loan terms'']::text[]','''Manage loan terms'',''Manage currency exchange'',''View currency reports'']::text[]');EXECUTE d;END $$;
CREATE FUNCTION public.manage_fx_currency(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid:=nullif(p->>'id','')::uuid;c text:=upper(trim(p->>'code'));n text:=trim(p->>'name');old public.fx_currencies;BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Owner access required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('fx-directory',0));IF cid IS NOT NULL THEN SELECT * INTO old FROM public.fx_currencies WHERE id=cid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Currency not found';END IF;END IF;IF p->>'action'='Remove' THEN IF cid IS NULL THEN RAISE EXCEPTION 'Choose a currency';END IF;IF EXISTS(SELECT 1 FROM public.fx_entries WHERE currency=old.code) THEN RAISE EXCEPTION 'Currency has transaction history; deactivate it instead';END IF;DELETE FROM public.fx_currencies WHERE id=cid;ELSE IF c IS NULL OR c !~ '^[A-Z]{3}$' OR c='LKR' OR n IS NULL OR length(n)=0 THEN RAISE EXCEPTION 'Enter a three-letter foreign currency code and name';END IF;IF old.code IS NOT NULL AND old.code<>c AND EXISTS(SELECT 1 FROM public.fx_entries WHERE currency=old.code) THEN RAISE EXCEPTION 'Used currency codes cannot be changed';END IF;IF cid IS NULL THEN INSERT INTO public.fx_currencies(code,name,active) VALUES(c,n,coalesce((p->>'active')::boolean,true)) RETURNING id INTO cid;ELSE UPDATE public.fx_currencies SET code=c,name=n,active=coalesce((p->>'active')::boolean,true) WHERE id=cid;END IF;END IF;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),NULL,'Currency directory','Updated',CASE WHEN p->>'action'='Remove' THEN 'Removed foreign currency '||old.code ELSE 'Saved foreign currency '||c||' · '||n END,cid::text);RETURN cid;END $$;
REVOKE ALL ON FUNCTION public.manage_fx_currency(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_fx_currency(jsonb) TO authenticated;
CREATE FUNCTION public.record_fx_entry(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=p->>'branch_id';c text:=upper(trim(p->>'currency'));k text:=p->>'kind';a numeric:=(p->>'amount')::numeric;r numeric:=(p->>'rate')::numeric;t numeric;cost numeric:=0;profit numeric:=0;cash public.fx_accounts;holding public.fx_accounts;eid uuid;BEGIN IF NOT public.staff_can('Manage currency exchange',b) THEN RAISE EXCEPTION 'Currency exchange permission required';END IF;IF NOT EXISTS(SELECT 1 FROM public.branches WHERE id=b AND active) THEN RAISE EXCEPTION 'Choose an active branch';END IF;IF k IS NULL OR k NOT IN('Buy','Sell','Funding','Withdrawal') OR a IS NULL OR a<=0 OR a::text IN('NaN','Infinity','-Infinity') OR a<>round(a,2) OR r IS NULL OR r<=0 OR r::text IN('NaN','Infinity','-Infinity') OR r<>round(r,6) THEN RAISE EXCEPTION 'Enter a positive amount (up to 2 decimals) and rate (up to 6 decimals)';END IF;IF c='LKR' AND (k IN('Buy','Sell') OR r<>1) THEN RAISE EXCEPTION 'LKR is only for exchange funding or withdrawal at rate 1';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('fx-directory',0));IF c IS NULL OR (c<>'LKR' AND NOT EXISTS(SELECT 1 FROM public.fx_currencies WHERE code=c AND active)) THEN RAISE EXCEPTION 'Choose an active currency';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('fx-branch-'||b,0));INSERT INTO public.fx_accounts(branch_id,currency) VALUES(b,'LKR') ON CONFLICT DO NOTHING;INSERT INTO public.fx_accounts(branch_id,currency) VALUES(b,c) ON CONFLICT DO NOTHING;SELECT * INTO cash FROM public.fx_accounts WHERE branch_id=b AND currency='LKR' FOR UPDATE;SELECT * INTO holding FROM public.fx_accounts WHERE branch_id=b AND currency=c FOR UPDATE;t:=round(a*r,2);IF t<=0 THEN RAISE EXCEPTION 'Total must be at least LKR 0.01';END IF;
IF k='Funding' THEN UPDATE public.fx_accounts SET balance=balance+a,cost_lkr=cost_lkr+CASE WHEN c='LKR' THEN 0 ELSE t END WHERE branch_id=b AND currency=c;cost:=CASE WHEN c='LKR' THEN 0 ELSE t END;
ELSIF k='Withdrawal' THEN IF holding.balance<a THEN RAISE EXCEPTION 'Insufficient exchange account balance';END IF;cost:=CASE WHEN c='LKR' THEN 0 WHEN a=holding.balance THEN holding.cost_lkr ELSE round(holding.cost_lkr*a/holding.balance,2) END;UPDATE public.fx_accounts SET balance=balance-a,cost_lkr=cost_lkr-cost WHERE branch_id=b AND currency=c;
ELSIF k='Buy' THEN IF cash.balance<t THEN RAISE EXCEPTION 'Insufficient LKR exchange funds; fund the separate account first';END IF;UPDATE public.fx_accounts SET balance=balance-t WHERE branch_id=b AND currency='LKR';UPDATE public.fx_accounts SET balance=balance+a,cost_lkr=cost_lkr+t WHERE branch_id=b AND currency=c;cost:=t;
ELSE IF holding.balance<a THEN RAISE EXCEPTION 'Insufficient foreign currency balance';END IF;cost:=CASE WHEN a=holding.balance THEN holding.cost_lkr ELSE round(holding.cost_lkr*a/holding.balance,2) END;profit:=t-cost;UPDATE public.fx_accounts SET balance=balance-a,cost_lkr=cost_lkr-cost WHERE branch_id=b AND currency=c;UPDATE public.fx_accounts SET balance=balance+t WHERE branch_id=b AND currency='LKR';END IF;
INSERT INTO public.fx_entries(branch_id,currency,kind,amount,rate,lkr_total,cost_lkr,profit_lkr,counterparty,reference,note,created_by) VALUES(b,c,k,a,r,t,cost,profit,trim(coalesce(p->>'counterparty','')),trim(coalesce(p->>'reference','')),trim(coalesce(p->>'note','')),auth.uid()) RETURNING id INTO eid;RETURN eid;END $$;
REVOKE ALL ON FUNCTION public.record_fx_entry(jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.record_fx_entry(jsonb) TO authenticated;
CREATE FUNCTION public.audit_fx_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(NEW.created_by,coalesce((SELECT display_name FROM public.profiles WHERE id=NEW.created_by),'Staff'),NEW.branch_id,'Currency exchange',NEW.kind,CASE NEW.kind WHEN 'Buy' THEN 'Bought ' WHEN 'Sell' THEN 'Sold ' WHEN 'Funding' THEN 'Funded exchange account with ' ELSE 'Withdrew from exchange account ' END||NEW.amount||' '||NEW.currency||' · LKR '||NEW.lkr_total,NEW.id::text);RETURN NEW;END $$;
CREATE TRIGGER audit_fx_entry AFTER INSERT ON public.fx_entries FOR EACH ROW EXECUTE FUNCTION public.audit_fx_entry();